CREATE TABLE public.site_text (key text PRIMARY KEY, page text NOT NULL, section text NOT NULL DEFAULT 'wording', label text NOT NULL, current_value text NOT NULL, default_value text NOT NULL, previous_value text, visibility text NOT NULL DEFAULT 'public', route text NOT NULL, max_length integer NOT NULL DEFAULT 2000, last_edited_at timestamptz, last_edited_by uuid, last_editor_name text);
GRANT SELECT ON public.site_text TO anon,authenticated;
GRANT UPDATE(current_value) ON public.site_text TO authenticated;
GRANT ALL ON public.site_text TO service_role;
ALTER TABLE public.site_text ENABLE ROW LEVEL SECURITY;
CREATE POLICY site_text_public_read ON public.site_text FOR SELECT TO anon,authenticated USING(visibility='public');
CREATE POLICY site_text_member_read ON public.site_text FOR SELECT TO authenticated USING(public.can_read_academic_content() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY site_text_admin_update ON public.site_text FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
INSERT INTO public.site_text(key,page,label,current_value,default_value,visibility,route,max_length)
SELECT CASE WHEN value='Your Medical Journey, Stronger Together.' THEN 'home.hero.headline' ELSE page||'.wording.'||ordinality END,page,left(btrim(value),70),value,value,CASE WHEN page='members' THEN 'members' ELSE 'public' END,CASE WHEN page IN ('home','header','footer') THEN '/' WHEN page='shared' THEN '/contact' WHEN page='members' THEN '/community' ELSE '/'||page END,CASE WHEN length(value)>160 THEN greatest(2000,length(value)*2) ELSE 300 END
FROM jsonb_each($seed${"home":["Connecting Medical Minds, Building Better Futures.","Your Medical Journey, Stronger Together.","Connect with Medicine and Surgery students across Nigerian universities, exchange knowledge, discover opportunities, and grow alongside people who understand your journey.","Become a Member ","Explore Our Community","Our mission","Different Universities. One Medical Family.","Medical school can feel isolating, but students across Nigeria are facing the same questions, the same exams and the same doubts. MedKonet brings them together.","We connect students so they can share resources, discuss difficult concepts, find study partners, support one another and build meaningful academic relationships that last beyond graduation.","What we offer","Built around collaboration","Community benefits","What members gain","MedKonet is a place to grow, not to compete.","You Don't Have to Figure It All Out Alone.","Whether you feel uncertain, overwhelmed or unsure how to reach your medical dreams, you belong here. Find encouragement, ask questions, share your challenges and learn alongside peers without fear of unhealthy competition.","Where we're heading","Our growth vision","These are ambitions we are working towards as the community grows. They are not yet in place.","Your Journey Matters. Let's Grow Together.","Apply to Join MedKonet","Student Networking","Meet medical students from federal, state and private universities across Nigeria.","Academic Resource Sharing","Exchange notes, references and study materials with peers who understand your curriculum.","Peer Learning","Talk through difficult concepts together and learn from how others approach them.","Mentorship and Guidance","Learn from students further along the journey as our mentorship vision grows.","Study Partnerships","Find supportive study partners who keep you accountable and encouraged.","Events and Academic Collaboration","Collaborate on academic initiatives with members from other schools.","Build connections across universities","Access shared academic resources","Learn from fellow medical students","Find supportive study partners","Discover mentorship opportunities","Stay encouraged throughout medical school","Develop professional relationships","University chapters","Local chapters in medical schools across the country.","Mentorship initiatives","Structured guidance from senior students and professionals.","Academic resources","A growing, member-contributed library of study materials.","Events and collaborations","Academic sessions and partnerships that bring members together."],"about":["About MedKonet","Different Universities. One Medical Family.","MedKonet Nigeria is a growing community connecting Medicine and Surgery students across federal, state and private universities in Nigeria.","Who we are","We are medical students who believe the journey through medical school is better shared. MedKonet brings students together for academic collaboration, peer learning, resource sharing, mentorship and friendship.","Our mission","To connect medical students across Nigeria so they can learn together, support one another and grow into compassionate, competent doctors.","Our vision","A nationwide medical student network where no student feels alone and every student has access to peers, guidance and opportunities.","Why MedKonet exists","Many students feel uncertain, overwhelmed or afraid of how to achieve their medical dreams. Too often, the environment rewards competition over cooperation. We exist to offer a different path: one built on encouragement and shared effort.","Core values","What guides us","Our commitment to collaboration and belonging","We commit to keeping MedKonet a respectful, welcoming and supportive space where members share generously, ask freely and celebrate each other's progress.","Apply to Join MedKonet","Collaboration","We learn more together than alone.","Compassion","We treat each other with kindness, as future doctors should.","Academic excellence","We pursue high standards and help each other reach them.","Belonging","Every medical student has a place here, whatever their university.","Integrity","We are honest, credit others and respect privacy.","Growth","We support each other's academic and personal development."],"contact":["Contact","We'd love to hear from you","Questions about MedKonet or your application? Reach us through WhatsApp or email."],"join":["Membership","Join MedKonet","Registration is currently closed","Thank you for your interest. Please contact the MedKonet team for updates. Existing members can still log in.","Login","Membership application","Tell us a little about yourself. Applications are reviewed by the MedKonet team.","Your account","Full name","Email address","Password","Hide password","Show password","Confirm password","WhatsApp number (required)","e.g. 0803 123 4567 or +234 803 123 4567. International numbers: include the country code.","Your studies","University","University type","State","Course","Current academic level","Why do you want to join MedKonet?","I agree to the","community rules"," and","privacy notice","log in"," Submitting…","Submit application","Already a member? ","Log in","Privacy notice","Read the full notice","Select type","Select state","Select level"],"login":["Welcome back","Log in to your MedKonet account.","Email address","Password","Hide password","Show password"," Logging in…","Log in","Forgot password?","New here? ","Join MedKonet"],"verify-email":["Verify your email","Enter the email address you applied with.","Email address","Continue","Verify Email","Resend code","Wrong email? Register again"],"privacy":["Privacy","Privacy Notice","What we collect","Your name, email, password (stored securely by our authentication service, never visible to anyone), WhatsApp number, university, university type, state, course, academic level and your reason for joining.","How we protect it","Access is restricted at the database level. Applicants can only see their own application. Only administrators can view all applications.","Your choices","To ask about, correct or delete your information, email "],"community-rules":["Community","Community Rules","Treat every member with respect and kindness, regardless of university, level or background.","Collaborate rather than compete. Share knowledge generously and celebrate others' progress.","Do not share other members' personal details, including phone numbers and emails, outside the community.","Only share academic materials you have the right to share, and credit original authors.","No harassment, discrimination, hate speech, spam or commercial promotion.","Do not give medical advice to the public on behalf of MedKonet.","Be honest. Do not impersonate others or misrepresent your student status.","Administrators may remove members who repeatedly break these rules."],"forgot-password":["Forgot your password?","Back to login","Email address","Send reset link"],"reset-password":["Set a new password","Loading","Request a new one","New password","Confirm new password","Update password"],"header":["Skip to content","Main","Admin"," Student Dashboard"," Admin Dashboard"," Log out","Login","Join MedKonet","Open menu","Menu","Mobile","Student Dashboard","Log out","Home","About","Community","Resources","Mentorship","Events","Contact"],"footer":["A growing community connecting Medicine and Surgery students across Nigerian universities. Different Universities. One Medical Family.","Explore","Home","About","Contact","Join MedKonet","Login","Community","Academic Resources","Mentorship","Events and Programmes","University Representatives","Community Rules","Privacy Notice","WhatsApp (line 1)","WhatsApp (line 2)"," MedKonet Nigeria. Connecting Medical Minds, Building Better Futures."],"shared":["Why we collect it:"," to review your membership application and, if approved, invite you to the MedKonet WhatsApp community.","Who can see it:"," only you and MedKonet administrators.","Never published:"," your WhatsApp number and email address are never shown publicly or shared with other members.","WhatsApp","Chat with the MedKonet team on either line.","WhatsApp line 1","WhatsApp line 2","Email","Send an email"],"members":["Latest announcements","Announcements","No announcements have been published yet.","Pinned","Open resource","Preparing…","Get file link","Open / download file","Approved members","Academic Resources","Events and Programmes","Mentorship","A developing initiative for guidance, encouragement and shared learning.","Learn together. Build understanding across every stage of medical school.","Opportunities to learn, connect and grow together.","Guidance that grows with our community","MedKonet intends to develop peer guidance and structured or informal support. Mentors would share experience, encourage thoughtful learning and respect boundaries; mentees would bring questions, participate actively and take responsibility for their progress. This initiative is developing; published opportunities below will explain any available support and how to express interest.","Upcoming","Past","Search ","Search titles…","Category","All categories","Type","All types","No matching items. Try another search or filter.","Resources will appear here as our community grows. Your next learning opportunity is ahead.","No events have been published yet. Check back soon.","Mentorship opportunities will be announced here when they become available.","Published ","Online meeting","Who it is for:","Express interest:","Our Community","Different Universities. One Medical Family.","Learning with care, growing together","MedKonet connects Medicine and Surgery students through academic collaboration, encouragement and belonging. WhatsApp remains our primary space for group communication.","Participate respectfully. Listen, welcome different perspectives and avoid harassment or unhealthy competition.","Collaborate honestly: exchange explanations, ask questions and acknowledge contributors.","Share resources you have permission to distribute. Respect copyright, patient confidentiality and academic integrity.","Do not publish another member’s email, WhatsApp number or private information.","Community rules","Join the WhatsApp community"]}$seed$::jsonb) AS groups(page,texts),LATERAL jsonb_array_elements_text(texts) WITH ORDINALITY AS wording(value,ordinality);
CREATE FUNCTION public.site_text_edit_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF NEW.key IS DISTINCT FROM OLD.key OR NEW.page IS DISTINCT FROM OLD.page OR NEW.section IS DISTINCT FROM OLD.section OR NEW.label IS DISTINCT FROM OLD.label OR NEW.default_value IS DISTINCT FROM OLD.default_value OR NEW.visibility IS DISTINCT FROM OLD.visibility OR NEW.route IS DISTINCT FROM OLD.route OR NEW.max_length IS DISTINCT FROM OLD.max_length THEN RAISE EXCEPTION 'Text definitions are immutable'; END IF;
IF char_length(NEW.current_value)>OLD.max_length THEN RAISE EXCEPTION 'Maximum text length exceeded'; END IF;
IF NEW.current_value IS NOT DISTINCT FROM OLD.current_value THEN RETURN OLD; END IF;
NEW.previous_value:=OLD.current_value; NEW.last_edited_at:=now(); NEW.last_edited_by:=auth.uid();
SELECT full_name INTO NEW.last_editor_name FROM public.profiles WHERE id=auth.uid(); NEW.last_editor_name:=coalesce(NEW.last_editor_name,'Administrator');
INSERT INTO public.audit_log(actor_id,action,details) VALUES(auth.uid(),'site_text.update',jsonb_build_object('key',OLD.key,'page',OLD.page,'old_value',OLD.current_value,'new_value',NEW.current_value)); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.site_text_edit_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER site_text_edit_guard BEFORE UPDATE ON public.site_text FOR EACH ROW EXECUTE FUNCTION public.site_text_edit_guard();
CREATE FUNCTION public.edit_site_text(_key text,_value text,_expected text) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ DECLARE item public.site_text; BEGIN
IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
SELECT * INTO item FROM public.site_text WHERE key=_key FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown text'; END IF;
IF item.current_value IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'This text changed since you opened it. Reload and try again.'; END IF;
IF char_length(_value)>item.max_length THEN RAISE EXCEPTION 'Maximum text length exceeded'; END IF;
UPDATE public.site_text SET current_value=_value WHERE key=_key; END $$;
REVOKE ALL ON FUNCTION public.edit_site_text(text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.edit_site_text(text,text,text) TO authenticated;